import {TREE_NODES} from './prestige.js';
export function paintPrestige(prestige){const put=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value;};put('prestige-count','転生 '+prestige.rebirthCount+'回');put('prestige-points','◆ '+prestige.currency);put('prestige-cycle','CYCLE '+prestige.cycle);put('prestige-open',prestige.canRebirth?'転生できます ◆':'転生 / スキル');put('prestige-cycle-progress',prestige.clearedStages+' / 4 STAGES');put('prestige-legacy',prestige.legacy?'旧セーブの解放・永久強化を引き継いでいます':'');put('rebirth-gain','再生コア +'+prestige.reward+' · 基礎生産 ×'+(1+2*(prestige.rebirthCount+1)));const preview=document.getElementById('rebirth-preview');if(preview){preview.disabled=!prestige.canRebirth;preview.textContent=prestige.canRebirth?'転生内容を確認':'4ステージ制覇で転生';}for(let i=0;i<4;i++)document.getElementById('prestige-seal-'+i)?.classList.toggle('complete',i<prestige.clearedStages);const result=document.getElementById('rebirth-from-result');if(result)result.hidden=!prestige.canRebirth;const tree=document.getElementById('prestige-tree');if(!tree)return;const signature=JSON.stringify([prestige.rebirthCount,prestige.currency,prestige.ranks,prestige.legacy]);if(tree.dataset.state===signature)return;tree.dataset.state=signature;const titles={runner:'RUNNER',automation:'ARCADE / AUTO',math:'MATHEMATICS'};tree.innerHTML=['runner','automation','math'].map(branch=>`<div class="tree-branch"><h3>${titles[branch]}</h3>${TREE_NODES.filter(n=>n.branch===branch).map(n=>{const o=prestige.offerNode(n.id),state=o.canBuy?'available':o.rank?'owned':'locked';return `<button data-tree-node="${n.id}" data-tree-token="${o.token}" class="tree-node ${state}" ${o.canBuy?'':'disabled'} aria-label="${n.name} ランク${o.rank}。${o.unlockText||o.effect}"><span class="tree-icon">${n.icon}</span><strong>${n.name}</strong><b>${o.rank} / ${n.maxRank}</b><small>${o.effect}</small><em>${o.maxed?'MAX':o.locked?o.unlockText:'◆ '+o.cost}</em></button>`;}).join('')}</div>`).join('');}
